390	// TestWorstResponseTimeDifferential compares the bounded fixed-point
391	// computation against a direct iteration of the RTA recurrence on random
392	// small task sets.
393	func TestWorstResponseTimeDifferential(t *testing.T) {
394		seed := rand.New(rand.NewSource(0x5eed))
395		for iter := 0; iter < 5000; iter++ {
396			n := 1 + seed.Intn(6)
397			tasks := make([]periodicTask, n)
398			prios := seed.Perm(n)
399			large := iter%3 == 0
400			for i := 0; i < n; i++ {
401				c := int64(1 + seed.Intn(5))
402				if large {
403					c = int64(1 + seed.Intn(50))
404				}
405				tp := c + int64(seed.Intn(map[bool]int{true: 4000, false: 20}[large]))
406				d := c + int64(seed.Intn(int(tp-c+1)))
407				if large {
408					// occasionally a wide gap between deadline and period
409					if seed.Intn(4) == 0 {
410						d = c + int64(seed.Intn(int(tp-c+1)))
411					}
412				}
413				tasks[i] = periodicTask{
414					id:        "t" + strconv.Itoa(i),
415					priority:  int64(prios[i]),
416					execution: c,
417					period:    tp,
418					deadline:  d,
419				}
420			}
421			for i, tk := range tasks {
422				var hp []periodicTask
423				u := new(big.Rat)
424				for _, h := range tasks {
425					if h.priority < tk.priority {
426						hp = append(hp, h)
427						u.Add(u, new(big.Rat).SetFrac(big.NewInt(h.execution), big.NewInt(h.period)))
428					}
429				}
430				got := worstResponseTime(tk, hp)
431	
432				// Reference: iterate w0=C, w_{k+1}=C+sum ceil(w/Tj)*Cj until a
433				// fixed point or a value past the deadline. When hp utilization is
434				// at least 1 there is no fixed point; small random deadlines keep
435				// the reference walk bounded.
436				var want *int64
437				w := tk.execution
438				if u.Cmp(big.NewRat(1, 1)) < 0 && w <= tk.deadline {
439					for steps := 0; steps <= int(tk.deadline)+1; steps++ {
440						next := tk.execution
441						for _, h := range hp {
442							next += ((w + h.period - 1) / h.period) * h.execution
443						}
444						if next == w {
445							v := w
446							want = &v
447							break
448						}
449						if next > tk.deadline {
450							break
451						}
452						w = next
453					}
454				}
455	
456				if (got == nil) != (want == nil) {
457					t.Fatalf("iter %d task %d %+v hp=%+v: got %v, want %v",
458						iter, i, tk, hp, got, want)
459				}
460				if got != nil && *got != *want {
461					t.Fatalf("iter %d task %d %+v: got %d, want %d", iter, i, tk, *got, *want)
462				}
463			}
464		}
465	}
466	
467	func TestPeriodicGeometricFixedPointBoundary(t *testing.T) {
468		// hp tasks C=1 at periods 2,4,...,2^m: own R = 2^m. With m=39 every
469		// period is legal (<= 1e12) and R = 549755813888.
470		const m = 39
471		r := int64(1) << m
472		build := func(deadline int64) string {
473			var b strings.Builder
474			b.WriteString(`{"tasks":[{"id":"low","priority":255,"execution":1,"period":1000000000000,"deadline":` +
475				strconv.FormatInt(deadline, 10) + `}`)
476			for j := 0; j < m; j++ {
477				tp := int64(1) << uint(j+1)
478				b.WriteString("," + periodicTaskObj("h"+strconv.Itoa(j), int64(j), 1, tp, tp))
479			}
480			b.WriteString("]}")
481			return b.String()
482		}
483		// Deadline equal to the fixed point meets exactly.
484		resp := periodicOK(t, build(r))
485		low := resp.Results[0]
486		if !resp.Schedulable || low.ResponseTime == nil || *low.ResponseTime != r {
487			t.Fatalf("D=R: %+v schedulable=%v", low, resp.Schedulable)
488		}
489		// One time unit tighter: the same fixed point now misses.
490		resp = periodicOK(t, build(r-1))
491		low = resp.Results[0]
492		if resp.Schedulable || low.ResponseTime != nil || low.DeadlineStatus != "missed" {
493			t.Fatalf("D=R-1: %+v schedulable=%v", low, resp.Schedulable)
494		}
495	}
496	
497	func TestPeriodicNearSaturationExact(t *testing.T) {
498		// d = 1-U = 1e-12 with own C=1, D=1e12: g(1e12)=1e12 is a fixed point
499		// meeting the deadline exactly; high-precision path must not round it off.
500		resp := periodicOK(t, `{"tasks":[
501			{"id":"low","priority":1,"execution":1,"period":1000000000000,"deadline":1000000000000},
502			{"id":"hi","priority":0,"execution":999999999999,"period":1000000000000,"deadline":1000000000000}
503		]}`)
504		low := resp.Results[0]
505		if !resp.Schedulable || low.ResponseTime == nil || *low.ResponseTime != 1_000_000_000_000 {
506			t.Fatalf("near-saturation result: %+v schedulable=%v", low, resp.Schedulable)
507		}
508	}
509	
510	func TestPeriodicUtilizationOneBoundaryVariants(t *testing.T) {
511		// 1/2 + 1/3 + 1/6 = 1 exactly: lowest-priority task must miss, and the
512		// exact-rational gray-zone path must classify it (no float shortcut).
513		resp := periodicOK(t, `{"tasks":[
514			{"id":"low","priority":3,"execution":1,"period":100,"deadline":100},
515			{"id":"a","priority":0,"execution":1,"period":2,"deadline":2},
516			{"id":"b","priority":1,"execution":1,"period":3,"deadline":3},
517			{"id":"c","priority":2,"execution":1,"period":6,"deadline":6}
518		]}`)
519		if resp.Schedulable {
520			t.Fatalf("schedulable = true, want false: %+v", resp.Results)
521		}
522		if low := resp.Results[0]; low.ResponseTime != nil || low.DeadlineStatus != "missed" {
523			t.Fatalf("low = %+v", low)
524		}
525		for i := 1; i <= 3; i++ {
526			if r := resp.Results[i]; r.ResponseTime == nil || r.DeadlineStatus != "met" {
527				t.Fatalf("%s = %+v, want met", r.ID, r)
528			}
529		}
530	}
