	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(resp)
}

// validatePeriodicSimRequest mirrors validatePeriodicRequest for the fields
// shared with the WCRT endpoint and additionally checks horizon and offset.
func validatePeriodicSimRequest(req *periodicSimRequest) ([]periodicTask, bool) {
	if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
		return nil, false
	}
	if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
		return nil, false
	}
	horizon := *req.Horizon
	tasks := make([]periodicTask, 0, len(*req.Tasks))
	ids := make(map[string]struct{}, len(*req.Tasks))
	priorities := make(map[int64]struct{}, len(*req.Tasks))
	var jobCount int64
	for i := range *req.Tasks {
		in := (*req.Tasks)[i]
		if !validTaskID(in.ID) {
			return nil, false
		}
		if _, dup := ids[in.ID]; dup {
			return nil, false
		}
		ids[in.ID] = struct{}{}
		if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
			return nil, false
		}
		if _, dup := priorities[*in.Priority]; dup {
			return nil, false
		}
		priorities[*in.Priority] = struct{}{}
		if in.Execution == nil || *in.Execution <= 0 || *in.Execution > maxPeriodicValue {
			return nil, false
		}
		if in.Period == nil || *in.Period <= 0 || *in.Period > maxPeriodicValue {
			return nil, false
		}
		if in.Deadline == nil || *in.Deadline <= 0 || *in.Deadline > maxPeriodicValue ||
			*in.Deadline > *in.Period {
			return nil, false
		}
		offset := int64(0)
		if in.Offset != nil {
			offset = *in.Offset
		}
		if offset < 0 || offset >= *in.Period || offset >= horizon {
			return nil, false
		}
		// Jobs release at offset+k*period while strictly below horizon. Since
		// offset < period, count = ceil((horizon-offset)/period), computed
		// without overflow (all operands are at most 1e12).
		count := (horizon-offset+*in.Period-1)/ *in.Period
		if count > maxPeriodicJobs-jobCount {
			return nil, false
		}
		jobCount += count
		tasks = append(tasks, periodicTask{
			id:        in.ID,
			priority:  *in.Priority,
			execution: *in.Execution,
			period:    *in.Period,
			deadline:  *in.Deadline,
			offset:    offset,
		})
	}
	return tasks, true
}

// periodicJob is one expanded release of a task; jobs are numbered from zero
// per task. idx pairs the (task index, job number) densely by release order.
type periodicJob struct {
	task      int
	job       int64
	release   int64
	remaining int64
	executed  int64
}

// readyItem is one heap entry; reusing stale entries (instead of fixing the
// heap on every release) keeps releases O(log J).
type readyItem struct {
	jobIdx  int
	prio    int64
	release int64
	task    int
	job     int64
	version int64
}

type readyHeap struct {
	items []*readyItem
}

func (h readyHeap) Len() int { return len(h.items) }
func (h readyHeap) Less(i, j int) bool {
	a, b := h.items[i], h.items[j]
	if a.prio != b.prio {
		return a.prio < b.prio
	}
	if a.release != b.release {
		return a.release < b.release
	}
	if a.task != b.task {
		return a.task < b.task
	}
	return a.job < b.job
}
func (h readyHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *readyHeap) Push(x any)   { h.items = append(h.items, x.(*readyItem)) }
func (h *readyHeap) Pop() any {
	old := h.items
	n := len(old)
	it := old[n-1]
	h.items = old[:n-1]
	return it
}

type periodicSeg struct {
	task      int
	job       int64
	start     int64
	end       int64
}

// simulatePeriodic runs an event-driven single-core fixed-priority fully
// preemptive simulation over [0, horizon): jobs of one task release at
// offset+k*period below the horizon, each with the same execution demand and a
// relative deadline. Overdue jobs keep running; the processor picks the ready
// job with the numerically smallest priority, ties resolved by release time,
// input order, then job number (so same-priority releases never preempt and a
// task's jobs run in number order). Idle periods advance to the next release.
func simulatePeriodic(tasks []periodicTask, horizon int64) periodicSimResponse {
	nt := len(tasks)

	// Release metadata: tasks and per-task next-job cursors, advanced lazily.
	type taskCursor struct {
		nextJob   int64
		nextStart int64 // task index of its first job in the flat arrays
	}
	cursors := make([]taskCursor, nt)
	totalJobs := 0
	for i, t := range tasks {
		cursors[i].nextJob = 0
		cursors[i].nextStart = totalJobs
		count := int((horizon-t.offset+t.period-1)/t.period)
		totalJobs += count
	}

	jobs := make([]periodicJob, 0, totalJobs)
	// releaseAt[k] is the flat index of the first job not yet released at the
	// start of each task's run of jobs releasing exactly at the current time.
	type releaseBatch struct {
		time int64
	}
	_ = releaseBatch{}

	// Build a merge stream over the per-task release sequences without
	// materializing a global sorted list: n cursors, each pointing at the next
	// (release time, task) pair.
	nextReleaseOf := func(i int, k int64) int64 {
		return tasks[i].offset + k*tasks[i].period
	}
	cursorJob := make([]int64, nt)
	for i := range cursorJob {
		cursorJob[i] = 0
	}
	remainingTaskJobs := make([]int, nt)
	for i, t := range tasks {
		remainingTaskJobs[i] = int((horizon - t.offset + t.period - 1) / t.period)
	}
	pendingReleases := nt // tasks still having at least one release ahead
	earliestPending := func() (time int64, task int) {
		first := true
		for i := 0; i < nt; i++ {
			if remainingTaskJobs[i] == 0 {
				continue
			}
			rt := nextReleaseOf(i, cursorJob[i])
			if first || rt < time {
				time, task, first = rt, i, false
			}
		}
		return time, task
	}

	// expand appends the job for task i's k-th release.
	versions := make([]int64, 0, totalJobs)
	expand := func(i int, k int64) int {
		idx := len(jobs)
		jobs = append(jobs, periodicJob{
			task:      i,
			job:       k,
			release:   nextReleaseOf(i, k),
			remaining: tasks[i].execution,
		})
		versions = append(versions, 0)
		return idx
	}

	ready := &readyHeap{}
	heap.Init(ready)
	pushReady := func(idx int) {
		j := &jobs[idx]
		versions[idx]++
		heap.Push(ready, &readyItem{
			jobIdx:  idx,
			prio:    tasks[j.task].priority,
			release: j.release,
			task:    j.task,
			job:     j.job,
			version: versions[idx],
		})
	}
	// popReady skips stale entries and finished jobs.
	popReady := func() int {
		for ready.Len() > 0 {
			it := heap.Pop(ready).(*readyItem)
			if it.version != versions[it.jobIdx] || jobs[it.jobIdx].remaining <= 0 {
				continue
			}
			return it.jobIdx
		}
		return -1
}
	peekReady := func() int {
		for ready.Len() > 0 {
			it := ready.items[0]
			if it.version != versions[it.jobIdx] || jobs[it.jobIdx].remaining <= 0 {
				heap.Pop(ready)
				continue
			}
			return it.jobIdx
		}
		return -1
	}

	var segments []periodicSeg
	current := -1
	var now int64

	// releaseDue moves every job releasing at or before now into the ready set.
	releaseDue := func(upto int64) {
		for {
			rt, ti := earliestPending()
			if pendingReleases == 0 || rt > upto {
				return
			}
			idx := expand(ti, cursorJob[ti])
			cursorJob[ti]++
			remainingTaskJobs[ti]--
			if remainingTaskJobs[ti] == 0 {
				pendingReleases--
			}
			pushReady(idx)
		}
	}
	nextReleaseTime := func() (int64, bool) {
		if pendingReleases == 0 {
			return 0, false
		}
		rt, _ := earliestPending()
		return rt, true
	}

	for now < horizon {
		releaseDue(now)
		if current >= 0 && jobs[current].remaining <= 0 {
			current = -1
		}
		if current == -1 {
			if best := peekReady(); best >= 0 {
				current = best
			}
		}

		if current == -1 {
			// Idle: jump to the next release, or finish if none remains.
			rt, ok := nextReleaseTime()
			if !ok {
				now = horizon
				break
			}
			now = rt
			continue
		}

		// The current job runs until it completes, the horizon arrives, or a
		// strictly higher-priority job releases.
		runEnd := horizon
		if rem := jobs[current].remaining; rem < horizon-now {
			runEnd = now + rem
		}
		if pendingReleases > 0 {
			rt, ti := earliestPending()
			curPrio := tasks[jobs[current].task].priority
			_ = ti
			if rt > now && rt < runEnd {
				// Only a strictly higher-priority release preempts; if the
				// earliest release is not higher, scan every task for the
				// earliest higher-priority one (n <= 256).
				preempt := int64(0)
				found := false
				for i := 0; i < nt; i++ {
					if remainingTaskJobs[i] == 0 || tasks[i].priority >= curPrio {
						continue
					}
					t := nextReleaseOf(i, cursorJob[i])
					if t > now && t < runEnd && (!found || t < preempt) {
						preempt, found = t, true
					}
				}
				if found {
					runEnd = preempt
				}
			}
		}

		segments = append(segments, periodicSeg{
			task:  jobs[current].task,
			job:   jobs[current].job,
			start: now,
			end:   runEnd,
		})
		delta := runEnd - now
		jobs[current].executed += delta
		jobs[current].remaining -= delta
		now = runEnd
		if jobs[current].remaining <= 0 {
			current = -1
		}
	}

	// Timeline: omit idle gaps and merge only adjacent segments of one job.
	timeline := make([]periodicTimelineInterval, 0, len(segments))
	for _, seg := range segments {
		if last := len(timeline) - 1; last >= 0 &&
			timeline[last].TaskID == tasks[seg.task].id &&
			timeline[last].Job == seg.job &&
			timeline[last].End == seg.start {
			timeline[last].End = seg.end
			continue
		}
		timeline = append(timeline, periodicTimelineInterval{
			TaskID: tasks[seg.task].id,
			Job:    seg.job,
			Start:  seg.start,
			End:    seg.end,
		})
	}

	// Results keep task input order; jobs are already in number order because
	// expansion follows release order per task.
	taskJobs := make([][]periodicJob, nt)
	for i := range taskJobs {
		taskJobs[i] = make([]periodicJob, 0)
	}
	for ji := range jobs {
		j := &jobs[ji]
		taskJobs[j.task] = append(taskJobs[j.task], *j)
	}
	results := make([]periodicTaskSimResult, nt)
	allDone := true
	for i, t := range tasks {
		jrs := make([]periodicJobResult, 0, len(taskJobs[i]))
		for _, j := range taskJobs[i] {
			deadline := j.release + t.deadline
			var completion *int64
			status := "pending"
			if j.remaining <= 0 {
				// Executed equals the full demand; the completion time is the
				// end of the job's last (merged or unmerged) timeline segment.
				c := completionOf(timeline, t.id, j.job, j.release)
				completion = &c
				if c <= deadline {
					status = "met"
				} else {
					status = "missed"
				}
			} else {
				allDone = false
				if deadline <= horizon {
					status = "missed"
				}
			}
			jrs = append(jrs, periodicJobResult{
				Job:              j.job,
				Release:          j.release,
				AbsoluteDeadline: deadline,
				Executed:         j.executed,
				Remaining:        j.remaining,
				Completion:       completion,
				DeadlineStatus:   status,
			})
		}
		results[i] = periodicTaskSimResult{ID: t.id, Jobs: jrs}
	}

	status := "horizon"
	if allDone {
		status = "completed"
	}
	return periodicSimResponse{Status: status, Timeline: timeline, Results: results}
}

// completionOf returns the end of the last timeline interval of the given job.
func completionOf(timeline []periodicTimelineInterval, taskID string, job int64, release int64) int64 {
	for k := len(timeline) - 1; k >= 0; k-- {
		if timeline[k].TaskID == taskID && timeline[k].Job == job {
			return timeline[k].End
		}
	}
	// A zero-demand path never reaches here (execution is strictly positive);
	// fall back to the release time.
	return release
}

