// refJob is the state of one job in the tick-by-tick reference simulation.
type refJob struct {
	task                int
	job                 int64
	release             int64
	executed, remain    int64
	completion          int64
}

// tickReference runs a plain one-microsecond-tick simulation with the same
// scheduling rules and returns the merged timeline plus per-job results.
func tickReference(tasks []periodicTask, horizon int64) ([]periodicTimelineInterval, []periodicJobResult) {
	nt := len(tasks)
	var jobs []*refJob
	// Per-task list of (release, job-number) released so far.
	released := make([][]*refJob, nt)
	cursor := make([]int64, nt)
	remaining := make([]int, nt)
	for i, t := range tasks {
		remaining[i] = int((horizon-t.offset+t.period-1)/t.period)
	}
	expand := func(upto int64) {
		for i := 0; i < nt; i++ {
			for remaining[i] > 0 {
				rt := tasks[i].offset + cursor[i]*tasks[i].period
				if rt > upto {
					break
				}
				j := &refJob{task: i, job: cursor[i], release: rt,
					remain: tasks[i].execution, completion: -1}
				jobs = append(jobs, j)
				released[i] = append(released[i], j)
				cursor[i]++
				remaining[i]--
			}
		}
	}
	type tick struct {
		task int
		job  int64
	}
	var ticks []tick
	current := (*refJob)(nil)
	for now := int64(0); now < horizon; now++ {
		expand(now)
		// Choose the best ready unfinished job, preempting only on strictly
		// higher priority; ordering is (priority, release, task, job).
		var best *refJob
		for _, j := range jobs {
			if j.remain <= 0 || j.release > now {
				continue
			}
			if current != nil && j == current {
				continue
			}
			if best == nil ||
				tasks[j.task].priority < tasks[best.task].priority ||
				(tasks[j.task].priority == tasks[best.task].priority &&
					(j.release < best.release ||
						(j.release == best.release && (j.task < best.task ||
							(j.task == best.task && j.job < best.job))))) {
				best = j
			}
		}
		if current == nil || current.remain <= 0 {
			current = best
		} else if best != nil && tasks[best.task].priority < tasks[current.task].priority {
			current = best
		}
		if current == nil {
			continue
		}
		ticks = append(ticks, tick{current.task, current.job})
		current.executed++
		current.remain--
		if current.remain == 0 {
			current.completion = now + 1
			current = nil
		}
	}
	expand(horizon - 1)

	// Merge adjacent ticks of the same job.
	var tl []periodicTimelineInterval
	for _, tk := range ticks {
		if last := len(tl) - 1; last >= 0 &&
			tl[last].TaskID == tasks[tk.task].id && tl[last].Job == tk.job &&
			tl[last].End == int64(len(tl)) {
			// end is positional below; fall through to simple build instead.
		}
		_ = tk
	}
	tl = nil
	for i, tk := range ticks {
		t := int64(i)
		if last := len(tl) - 1; last >= 0 &&
			tl[last].TaskID == tasks[tk.task].id && tl[last].Job == tk.job &&
			tl[last].End == t {
			tl[last].End = t + 1
			continue
		}
		tl = append(tl, periodicTimelineInterval{
			TaskID: tasks[tk.task].id, Job: tk.job, Start: t, End: t + 1,
		})
	}

	var results []periodicJobResult
	for i, t := range tasks {
		for _, j := range released[i] {
			deadline := j.release + t.deadline
			var c *int64
			var status string
			if j.completion >= 0 {
				v := j.completion
				c = &v
				if v <= deadline {
					status = "met"
				} else {
					status = "missed"
				}
			} else if deadline <= horizon {
				status = "missed"
			} else {
				status = "pending"
			}
			results = append(results, periodicJobResult{
				Job: j.job, Release: j.release, AbsoluteDeadline: deadline,
				Executed: j.executed, Remaining: j.remain,
				Completion: c, DeadlineStatus: status,
			})
		}
	}
	return tl, results
}

// TestPeriodicSimDifferential compares the event-driven simulation against a
// tick-by-tick reference over randomized task sets.
func TestPeriodicSimDifferential(t *testing.T) {
	seed := rand.New(rand.NewSource(0x5112))
	for iter := 0; iter < 400; iter++ {
		horizon := int64(1 + seed.Intn(120))
		n := 1 + seed.Intn(5)
		prios := seed.Perm(256)[:n]
		tasks := make([]periodicTask, n)
		var total int64
		for i := 0; i < n; i++ {
			period := int64(1 + seed.Intn(40))
			off := int64(seed.Intn(int(period)))
			if off >= horizon {
				off = horizon - 1
				if off >= period {
					off = period - 1
				}
			}
			execution := int64(1 + seed.Intn(15))
			deadline := int64(1 + seed.Intn(int(period)))
			tasks[i] = periodicTask{
				id:        "t" + strconv.Itoa(i),
				priority:  int64(prios[i]),
				execution: execution,
				period:    period,
				deadline:  deadline,
				offset:    off,
			}
			total += (horizon - off + period - 1) / period
		}
		if total > 5000 {
			continue
		}

		got := simulatePeriodic(tasks, horizon)
		wantTL, wantJobs := tickReference(tasks, horizon)

		if len(got.Timeline) != len(wantTL) {
			t.Fatalf("iter %d h=%d tasks=%+v\ntimeline got %s\nwant %s",
				iter, horizon, tasks, intervals(got.Timeline), intervals(wantTL))
		}
		for i := range wantTL {
			if got.Timeline[i] != wantTL[i] {
				t.Fatalf("iter %d h=%d tasks=%+v\ntimeline got %s\nwant %s",
					iter, horizon, tasks, intervals(got.Timeline), intervals(wantTL))
			}
		}

		var gotJobs []periodicJobResult
		for _, r := range got.Results {
			gotJobs = append(gotJobs, r.Jobs...)
		}
		if len(gotJobs) != len(wantJobs) {
			t.Fatalf("iter %d: job count got %d want %d", iter, len(gotJobs), len(wantJobs))
		}
		// Results group jobs by task; compare in that grouping order.
		wantByTask := make(map[int][]periodicJobResult)
		for _, j := range wantJobs {
			// identify task via release order — instead regroup below.
			_ = j
		}
		var wantRegrouped []periodicJobResult
		for i := range tasks {
			for _, j := range wantJobs {
				if j.Release == tasks[i].offset+ (j.Job*tasks[i].period) &&
					j.AbsoluteDeadline == tasks[i].offset+j.Job*tasks[i].period+tasks[i].deadline {
					// ambiguous across tasks is possible; dedupe by exact key.
				}
				_ = j
			}
		}
		_ = wantRegrouped
		// Build a stable comparison keyed on (task order, job number): rerun a
		// per-task index map from the reference via pointer-free grouping.
		key := func(j periodicJobResult) string {
			return strconv.FormatInt(j.Release, 10) + "/" + strconv.FormatInt(j.Job, 10)
		}
		// Group want jobs by (release, job) is ambiguous; use sorted structs
		// against the event response, which is deterministic in (task, job).
		gotFlat := append([]periodicJobResult(nil), gotJobs...)
		wantFlat := append([]periodicJobResult(nil), wantJobs...)
		sort.Slice(wantFlat, func(a, b int) bool {
			if wantFlat[a].Release != wantFlat[b].Release {
				return wantFlat[a].Release < wantFlat[b].Release
			}
			return wantFlat[a].Job < wantFlat[b].Job
		})
		sort.Slice(gotFlat, func(a, b int) bool {
			if gotFlat[a].Release != gotFlat[b].Release {
				return gotFlat[a].Release < gotFlat[b].Release
			}
			return gotFlat[a].Job < gotFlat[b].Job
		})
		if len(gotFlat) != len(wantFlat) {
			t.Fatalf("iter %d", iter)
		}
		for i := range wantFlat {
			// Release+job may collide between tasks; compare multiset of the
			// full struct except ordering by task identity.
			g, w := gotFlat[i], wantFlat[i]
			if g.Job != w.Job || g.Release != w.Release || g.AbsoluteDeadline != w.AbsoluteDeadline ||
				g.Executed != w.Executed || g.Remaining != w.Remaining ||
				(g.Completion == nil) != (w.Completion == nil) ||
				(g.Completion != nil && *g.Completion != *w.Completion) ||
				g.DeadlineStatus != w.DeadlineStatus {
				t.Fatalf("iter %d h=%d tasks=%+v\njob got %+v\nwant %+v", iter, horizon, tasks, g, w)
			}
		}
		_ = key

		// Status: completed iff the reference finished every released job.
		allDone := true
		for _, j := range wantJobs {
			if j.Completion == nil {
				allDone = false
			}
		}
		wantStatus := "horizon"
		if allDone {
			wantStatus = "completed"
		}
		if got.Status != wantStatus {
			t.Fatalf("iter %d: status got %s want %s", iter, got.Status, wantStatus)
		}
	}
}

