241		expandDue := func(upto int64) {
242			for i := 0; i < nt; i++ {
243				for remainingReleases(i) > 0 {
244					rt := releaseAt(i, nextJob[i])
245					if rt > upto {
246						break
247					}
248					idx := len(jobs)
249					jobs = append(jobs, periodicJob{
250						task:       i,
251						job:        nextJob[i],
252						release:    rt,
253						remaining:  tasks[i].execution,
254						completion: -1,
255					})
256					nextJob[i]++
257					heap.Push(ready, &readyItem{
258						jobIdx:  idx,
259						prio:    tasks[i].priority,
260						release: rt,
261						task:    i,
262						job:     jobs[idx].job,
263					})
264				}
265			}
266		}
267	
268		// nextReleaseTime reports the earliest future release across all tasks.
269		nextReleaseTime := func() (int64, bool) {
270			best := int64(0)
271			found := false
272			for i := 0; i < nt; i++ {
273				if remainingReleases(i) == 0 {
274					continue
275				}
276				rt := releaseAt(i, nextJob[i])
277				if !found || rt < best {
278					best, found = rt, true
279				}
280			}
281			return best, found
282		}
283	
284		// popReady drops entries of finished jobs and returns the best ready job.
285		popReady := func() int {
286			for ready.Len() > 0 {
287				it := heap.Pop(ready).(*readyItem)
288				if jobs[it.jobIdx].remaining > 0 {
289					return it.jobIdx
290				}
291			}
292			return -1
293		}
294		// peekReady is the non-consuming variant used to test preemption.
295		peekReady := func() int {
296			for ready.Len() > 0 {
297				it := (*ready)[0]
298				if jobs[it.jobIdx].remaining > 0 {
299					return it.jobIdx
300				}
301				heap.Pop(ready)
302			}
303			return -1
304		}
305	
306		var segments []periodicSeg
307		current := -1
308		var now int64
309		for now < horizon {
310			expandDue(now)
311			if current >= 0 && jobs[current].remaining <= 0 {
312				current = -1
313			}
314	
315			// Reschedule: take the best ready job when idle, or switch only when a
316			// strictly higher-priority job is ready (equal priority never preempts).
317			best := peekReady()
318			switch {
319			case current == -1:
320				current = popReady()
321			case best != -1 && tasks[jobs[best].task].priority < tasks[jobs[current].task].priority:
