func TestPeriodicSimSamePriorityDoesNotPreempt(t *testing.T) {
	// A and B share a priority; A0 runs at 0 (input order), B0 releases at 0
	// too and waits. B1 releases at 3 while A0 is still running; it must not
	// preempt. A0[0,4], then B0[4,7], B1[7,10].
	resp := periodicSimOK(t, `{"horizon":10,"tasks":[
		{"id":"A","priority":0,"execution":4,"period":10,"deadline":10},
		{"id":"B","priority":0,"execution":3,"period":3,"deadline":3}
	]}`)
	want := []periodicTimelineInterval{
		{TaskID: "A", Job: 0, Start: 0, End: 4},
		{TaskID: "B", Job: 0, Start: 4, End: 7},
		{TaskID: "B", Job: 1, Start: 7, End: 10},
	}
	if len(resp.Timeline) != len(want) {
		t.Fatalf("timeline = %s", intervals(resp.Timeline))
	}
	for i := range want {
		if resp.Timeline[i] != want[i] {
			t.Fatalf("timeline = %s", intervals(resp.Timeline))
		}
	}
}

